for item in FILES:
    path = ROOT / "canvas-fonts" / item["name"]
    url = "https://raw.githubusercontent.com/anthropics/skills/e4bb5d960d87126ff3b3a8af1a104b7db67560ba/skills/canvas-design/canvas-fonts/" + item["name"]
    data = urllib.request.urlopen(url, timeout=60).read()
    digest = hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()
    if digest != item["sha"]:
        raise ValueError("Font hash mismatch: " + item["name"])
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
print("Verified and restored", len(FILES), "fonts")
